export const getColores = () => JSON.parse(localStorage.getItem('colores'));
export const setColores = (colores) => localStorage.setItem('colores', JSON.stringify(colores));
export const removeColores = () => localStorage.removeItem('colores');


export const getEmpresa = () => JSON.parse(localStorage.getItem('empresa'));
export const setEmpresa = (empresa) => localStorage.setItem('empresa', JSON.stringify(empresa));
export const removeEmpresa = () => localStorage.removeItem('empresa');


export const getTallas = () => JSON.parse(localStorage.getItem('tallas'));
export const setTallas = (tallas) => localStorage.setItem('tallas', JSON.stringify(tallas));
export const removeTallas = () => localStorage.removeItem('tallas');


export const getMarcas = () => JSON.parse(localStorage.getItem('marcas'));
export const setMarcas = (marcas) => localStorage.setItem('marcas', JSON.stringify(marcas));
export const removeMarcas = () => localStorage.removeItem('marcas');
